import {analyzeArticle, validateGuide, buildChatGPTPrompt} from './engine.js';
import {DEMO_TEXT, DEMO_TITLE, DEMO_GUIDE} from './demo.js';

const paths={book:'M4 4h6a4 4 0 0 1 4 4v13a4 4 0 0 0-4-3H4z M14 8a4 4 0 0 1 4-4h4v14h-4a4 4 0 0 0-4 3',library:'M4 5v15 M9 5v15 M14 5v15 M18 4l4 15',review:'M20 7v5h-5 M20 12a8 8 0 1 0-2 6 M8 11l3 3 5-6',note:'M4 4h16v16H4z M8 8h8 M8 12h8 M8 16h5',help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',leaf:'M20 3c-2 8 2 15-8 17C1 21 2 7 20 3z M6 17l9-8',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6',file:'M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6 M9 16h6',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',left:'M19 12H5 M10 7l-5 5 5 5',chevron:'M9 5l7 7-7 7',search:'M20 20l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',check:'M5 12l4 4L20 5',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',audio:'M4 9h4l5-4v14l-5-4H4z M17 8a7 7 0 0 1 0 8 M20 5a11 11 0 0 1 0 14',focus:'M8 3H3v5 M16 3h5v5 M3 16v5h5 M21 16v5h-5 M9 9h6v6H9z',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',close:'M6 6l12 12 M6 18L18 6',download:'M12 3v13 M7 11l5 5 5-5 M4 17v4h16v-4',trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',copy:'M8 8h13v13H8z M16 8V3H3v13h5',external:'M14 3h7v7 M21 3L10 14 M10 3H3v18h18v-7',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1',pause:'M8 5v14 M16 5v14',play:'M8 4l12 8-12 8z',reset:'M4 4v6h6 M4 10a8 8 0 1 1 1 8',chat:'M3 4h18v13H9l-6 4z M7 8h10 M7 12h7',dots:'M5 12h.01 M12 12h.01 M19 12h.01',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-2a8 8 0 0 1 16 0v2',tag:'M3 3h8l10 10-8 8L3 11z M7 7h.01',moon:'M20 16A9 9 0 0 1 8 4a9 9 0 1 0 12 12'};
const icon=(n,cl='')=>`<svg class="icon ${cl}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog'),dc=document.querySelector('#dialog-content');
const STORAGE='lume.v1';
const demo=()=>({id:'demo',title:DEMO_TITLE,text:DEMO_TEXT,guide:structuredClone(DEMO_GUIDE),completed:[],notes:'',review:{},created:Date.now(),synthetic:true});
let data={articles:[demo()],settings:{minutes:15,large:false}};
try{const saved=JSON.parse(localStorage.getItem(STORAGE));if(saved&&Array.isArray(saved.articles)){data={...data,...saved,settings:{...data.settings,...saved.settings}};data.articles=data.articles.filter(a=>a&&typeof a.id==='string'&&typeof a.title==='string'&&typeof a.text==='string').map(a=>({...a,guide:validateGuide(a.guide),completed:Array.isArray(a.completed)?a.completed:[],notes:typeof a.notes==='string'?a.notes:'',review:a.review||{}}));}}catch{data={articles:[demo()],settings:{minutes:15,large:false}};}
let filter='all',query='',studyTab='guide',step=0,cardIndex=0,flipped=false,quizIndex=0,quizAnswer=null,aiAvailable=false,timerRunning=false,timerLeft=data.settings.minutes*60,timerDeadline=0,timerInterval,toastTimeout,focus=false;
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(data));return true}catch{toast('Armazenamento cheio. Exporte uma cópia para guardar seu estudo.');return false}}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.classList.remove('show'),4500)}
function article(){try{return data.articles.find(a=>a.id===decodeURIComponent((location.hash.split('/')[1]||'')))}catch{return undefined}}
function route(){return location.hash.slice(1).split('/')[0]||'library'}
function navigate(hash){if(location.hash==='#'+hash)render();else location.hash=hash}
function progress(a){return Math.round(a.completed.filter(id=>a.guide.sections.some(s=>s.id===id)).length/a.guide.sections.length*100)}
function minutes(a){return Math.max(2,Math.round(a.text.split(/\s+/).length/180))}
const navs=[['library','library','Biblioteca'],['review','review','Minha revisão'],['notes','note','Caderno'],['help','help','Como funciona']];
function shell(content){const r=route(),active=r==='study'?'library':r;app.innerHTML=`<aside class="sidebar"><a href="#library" class="brand" aria-label="Lume — biblioteca"><img src="icon.svg" alt="">lume</a><p class="brand-caption">UMA LEITURA DE CADA VEZ</p><nav class="nav" aria-label="Principal">${navs.map(([id,ic,t])=>`<button data-nav="${id}" class="${id===active?'active':''}">${icon(ic)}<span>${t}</span></button>`).join('')}</nav><div class="nav-divider"></div><div class="nav-label">SEU TEMPO, SEU RITMO</div><div class="focus-widget"><div class="eyebrow">${icon('leaf')}Um momento de foco</div><p>Um pequeno passo já conta.</p><div class="timer" data-timer>${formatTime(timerLeft)}</div><div class="timer-controls"><button data-action="timer" data-timer-label>${timerRunning?'Pausar':'Começar'}</button><button data-action="timer-reset" title="Reiniciar temporizador" aria-label="Reiniciar temporizador">↺</button></div></div><div class="profile"><div class="avatar">${icon('user')}</div><div><strong>Meu espaço</strong>Salvo neste navegador</div></div></aside><div class="workspace"><header class="topbar"><div class="mobile-logo"><img src="icon.svg" alt="">lume</div><div class="breadcrumbs">Meu espaço ${icon('chevron')} <strong>${navs.find(n=>n[0]===active)?.[2]||'Biblioteca'}</strong></div><div class="top-actions"><span class="save-label"><span class="dot"></span>${aiAvailable?'IA disponível':'Seu espaço de leitura'}</span><button class="icon-button" data-action="settings" aria-label="Preferências">${icon('settings')}</button></div></header><main id="main" class="content" tabindex="-1">${content}</main></div><button class="button focus-exit" data-action="focus">${icon('close')}Sair do foco</button><input class="file-hidden" id="article-file" type="file" accept=".pdf,.txt,.md,.json"><input class="file-hidden" id="backup-file" type="file" accept=".json">`;
app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));
app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b));
document.querySelector('#article-file').onchange=e=>readFile(e.target.files[0]);document.querySelector('#backup-file').onchange=e=>readFile(e.target.files[0]);
document.body.classList.toggle('large-text',data.settings.large);document.body.classList.toggle('focus-mode',focus);
}
const illustration=`<svg class="book-illustration" viewBox="0 0 280 165" fill="none" aria-hidden="true"><ellipse cx="140" cy="146" rx="110" ry="10" fill="#d5ddc8"/><path d="M43 76l99 25 96-25v47l-95 28-100-27z" fill="#8a9b70"/><path d="M45 74l99 22 93-23v43l-93 27-99-26z" fill="#f9f9ed" stroke="#bdc8ac"/><path d="M144 96v47 M48 85l91 23 M48 96l91 23 M48 106l91 24 M150 108l80-22 M150 119l80-22 M150 130l80-22" stroke="#d2d8c2"/><path d="M45 71l97 24 96-25-96-23z" fill="#a6b88c"/><path d="M65 54c23-12 52-6 76 8 28-14 53-22 78-12v53c-27-8-52-1-78 13-25-14-50-17-76-9z" fill="#fffff3" stroke="#9daf85"/><path d="M141 62v54" stroke="#b8c5a1"/><path d="M77 66c18-5 34-1 49 6 M77 76c18-5 34-1 49 6 M77 86c18-4 34-1 49 6 M155 72c18-8 33-12 50-9 M155 82c18-8 33-12 50-9 M155 92c18-8 33-12 50-9" stroke="#d0d9bf" stroke-width="2"/><path d="M185 7c5 15 4 27-10 39-5-14-3-27 10-39z" fill="#b4c3a0"/><path d="M169 17c-3 13-1 22 8 29 4-13 1-24-8-29z" fill="#d1dabc"/><path d="M177 44v12" stroke="#91a577"/><path d="M29 38v14 M22 45h14 M239 28v10 M234 33h10" stroke="#adbd94" stroke-width="1.5"/><circle cx="249" cy="62" r="2" fill="#b0c093"/></svg>`;
function library(){shell(`<div class="greeting">${icon('sun')}SEU ESPAÇO PARA APRENDER COM CALMA</div><div class="page-intro"><div><h1>Grandes ideias.<br><em>Pequenos passos.</em></h1><p>Transforme artigos científicos em conhecimento que fica.<br>Menos sobrecarga. Mais clareza. No seu ritmo.</p></div><div class="quiet-tag">${icon('leaf')}Uma ideia de cada vez</div></div><div class="hero-grid"><section class="import-card"><div class="card-heading"><div class="icon-tile">${icon('file')}</div><div><h2>Vamos entender um artigo?</h2><p>Seu próximo aprendizado começa aqui.</p></div></div><div class="dropzone" id="dropzone" role="button" tabindex="0" aria-label="Selecionar artigo PDF ou texto"><div class="upload-orb">${icon('upload')}</div><strong>Arraste seu artigo ou <u>escolha um arquivo</u></strong><span>PDF com texto, TXT ou Markdown · até 20 MB</span></div><div class="inline-actions"><button class="text-button" data-action="paste">${icon('note')}Colar o texto do artigo</button><button class="text-button" data-action="demo">Experimentar um exemplo ${icon('arrow')}</button></div><div class="privacy-note">${icon('shield')} Seu artigo fica neste navegador. Você escolhe quando usar IA.</div></section><aside class="illustration-card"><div class="eyebrow">UM PASSO DE CADA VEZ</div><h2>Entender.<br>Conectar. Lembrar.</h2><p>Aprender não precisa ser uma corrida.<br>A gente começa pelo essencial.</p><span class="sparkle">✧</span>${illustration}</aside></div><div class="features-strip"><span>${icon('focus')}Leitura em pequenas etapas</span><span>${icon('tag')}Jargões em linguagem simples</span><span>${icon('review')}Revisão para fixar</span></div><div class="section-heading"><h2>Sua biblioteca <span>${data.articles.length}</span></h2><button class="text-button" data-action="backup" title="Exportar biblioteca">${icon('download')}Salvar cópia</button></div><div class="library-tools"><div class="tabs" role="group" aria-label="Filtrar biblioteca">${[['all','Todos'],['reading','Em estudo'],['done','Concluídos']].map(([v,t])=>`<button data-filter="${v}" class="${filter===v?'active':''}" aria-pressed="${filter===v}">${t}</button>`).join('')}</div><label class="search">${icon('search')}<input id="search" aria-label="Buscar artigo" placeholder="Buscar na biblioteca" value="${esc(query)}"></label></div><div class="article-grid" id="article-grid">${libraryCards()}</div><div class="bottom-note">${icon('leaf')}Você não precisa entender tudo de uma vez. Só dar o próximo passo.</div><footer class="bottom-footer"><span>Feito para aprender, com espaço para respirar.</span><button data-action="about">Sobre o Lume ↗</button></footer>`);
const dz=document.querySelector('#dropzone');dz.onclick=pickFile;dz.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pickFile()}};dz.ondragover=e=>{e.preventDefault();dz.classList.add('drag')};dz.ondragleave=()=>dz.classList.remove('drag');dz.ondrop=e=>{e.preventDefault();dz.classList.remove('drag');readFile(e.dataTransfer.files[0])};document.querySelector('#search').oninput=e=>{query=e.target.value;refreshCards()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;library()});bindCards();}
function libraryCards(){const list=data.articles.filter(a=>(filter==='all'||(filter==='done'?progress(a)===100:progress(a)<100))&&a.title.toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')));return list.map(a=>`<article class="article-card"><div class="card-tags"><span class="pill">${icon('file')}PSICOLOGIA</span>${a.synthetic?'<span class="pill purple">EXEMPLO FICTÍCIO</span>':''}<button class="card-menu" data-menu="${esc(a.id)}" aria-label="Opções de ${esc(a.title)}">${icon('dots')}</button></div><h3>${esc(a.title)}</h3><div class="meta">${a.synthetic?'Material didático · ':''}${minutes(a)} min de leitura · ${a.guide.sections.length} etapas</div><div class="card-footer"><div class="progress-label"><span>${progress(a)===100?'Percurso concluído':progress(a)?'Em estudo':'Pronto para começar'}</span><span>${progress(a)}%</span></div><div class="progress"><div style="width:${progress(a)}%"></div></div><button class="open-card" data-open="${esc(a.id)}">${progress(a)?'Continuar meu estudo':'Começar meu estudo'} ${icon('arrow')}</button></div></article>`).join('')+`<button class="article-card new-card" data-action="upload">${icon('plus')}<h3>Adicionar um artigo</h3><p>Um novo tema, uma nova perspectiva.<br>O próximo passo é seu.</p></button>`+(list.length===0?'<div class="empty-state">Nenhum artigo por aqui. Experimente outro filtro ou adicione uma leitura.</div>':'');}
function refreshCards(){document.querySelector('#article-grid').innerHTML=libraryCards();bindCards()}
function bindCards(){document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openStudy(b.dataset.open));document.querySelectorAll('[data-menu]').forEach(b=>b.onclick=()=>articleMenu(b.dataset.menu));document.querySelectorAll('#article-grid [data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b))}
function openStudy(id){const a=data.articles.find(a=>a.id===id);if(!a)return;step=Math.max(0,a.guide.sections.findIndex(s=>!a.completed.includes(s.id)));studyTab='guide';cardIndex=0;quizIndex=0;quizAnswer=null;flipped=false;navigate('study/'+encodeURIComponent(id))}
function render(){if(!['study'].includes(route())){focus=false;stopSpeech()}switch(route()){case 'study':if(article())study();else navigate('library');break;case 'review':reviewPage();break;case 'notes':notesPage();break;case 'help':helpPage();break;default:library();}}
function modeNotice(a){if(a.synthetic)return `<div class="notice study-notice">Exemplo fictício para experimentar o Lume. Os dados e os resultados foram criados para ensinar; não representam uma pesquisa publicada.</div>`;if(a.guide.mode==='local')return `<div class="notice study-notice">Leitura guiada local: organiza trechos do seu texto e oferece perguntas de estudo. Para uma explicação didática personalizada, use “Explicar com IA”.</div>`;return `<div class="notice green study-notice">Guia gerado por IA. Confira as explicações com o original, especialmente números, conclusões e limitações.</div>`;}
function study(){const a=article();if(!a)return;step=Math.min(step,a.guide.sections.length-1);const tabs=[['guide','book','Percurso'],['glossary','tag','Conceitos'],['cards','review','Flashcards'],['quiz','check','Teste rápido'],['notes','note','Anotações'],['original','file','Original']];shell(`<button class="text-button back study-heading" data-action="library">${icon('left')}Voltar à biblioteca</button><div class="study-heading"><div class="card-tags"><span class="pill">${a.synthetic?'EXEMPLO FICTÍCIO':'MEU ARTIGO'}</span><span class="pill purple">${a.guide.mode==='ai'?'GUIA COM IA':a.synthetic?'GUIA DIDÁTICO':'LEITURA LOCAL'}</span><span class="tiny">${progress(a)}% do percurso</span></div><h1>${esc(a.title)}</h1><p>${esc(a.guide.overview)}</p></div><div class="study-toolbar"><button class="button primary" data-action="ai">${icon('spark')}Explicar com IA</button><button class="button" data-action="speak">${icon('audio')}Ouvir esta etapa</button><button class="button" data-action="focus">${icon('focus')}Modo foco</button><button class="button" data-action="export-article">${icon('download')}Exportar estudo</button></div>${modeNotice(a)}<details class="source study-notice" style="margin-bottom:20px"><summary>${icon('shield')}Cuidados e limites deste guia</summary><ul class="key-points">${a.guide.limitations.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details><div class="study-tabs" role="group" aria-label="Área do estudo">${tabs.map(([id,ic,t])=>`<button data-study-tab="${id}" class="${studyTab===id?'active':''}" aria-pressed="${studyTab===id}">${t}</button>`).join('')}</div><div class="focus-indicator"><span class="quiet-tag">${icon('leaf')}Uma etapa de cada vez · <span data-timer>${formatTime(timerLeft)}</span><button class="text-button" data-action="timer" data-timer-label>${timerRunning?'Pausar':'Começar'}</button></span></div>${studyTab==='guide'?lessonHtml(a):studyTab==='glossary'?glossaryHtml(a):studyTab==='cards'?cardsHtml(a):studyTab==='quiz'?quizHtml(a):studyTab==='notes'?notesHtml(a):originalHtml(a)}`);
app.querySelectorAll('[data-study-tab]').forEach(b=>b.onclick=()=>{stopSpeech();studyTab=b.dataset.studyTab;study()});app.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>setStep(Number(b.dataset.step)));const done=app.querySelector('#understood');if(done)done.onchange=e=>{const id=a.guide.sections[step].id;a.completed=a.completed.filter(x=>x!==id);if(e.target.checked)a.completed.push(id);persist();study();if(progress(a)===100)toast('Percurso concluído. Que tal revisar o que aprendeu?')};const note=app.querySelector('#note-editor');if(note)note.oninput=e=>{a.notes=e.target.value;persist();document.querySelector('#note-status').textContent='Salvo neste navegador'};app.querySelectorAll('[data-quiz-answer]').forEach(b=>b.onclick=()=>{if(quizAnswer!==null)return;quizAnswer=Number(b.dataset.quizAnswer);a.review.quiz={...(a.review.quiz||{}),[quizIndex]:quizAnswer};persist();study()});}
function lessonHtml(a){const s=a.guide.sections[step];return `<div class="study-layout"><aside class="study-nav" aria-label="Etapas do artigo"><div class="eyebrow">SEU PERCURSO · ${a.guide.sections.length} ETAPAS</div>${a.guide.sections.map((s,i)=>`<button data-step="${i}" class="${i===step?'active':''}" ${i===step?'aria-current="step"':''}><span class="step-count">${a.completed.includes(s.id)?'✓':String(i+1).padStart(2,'0')}</span><span>${esc(s.title)}</span></button>`).join('')}<div class="notice">Comece pelo essencial.<br>Volte aos detalhes quando fizer sentido para você.</div></aside><div class="study-main"><article class="lesson"><div class="card-tags"><span class="pill ${s.priority==='deepen'?'purple':''}">${s.priority==='deepen'?'PARA APROFUNDAR':'ESSENCIAL PARA ENTENDER'}</span><span class="tiny">Etapa ${step+1} de ${a.guide.sections.length}</span></div><h2>${esc(s.question||s.title)}</h2><div class="lead">${esc(s.summary)}</div><h3>${a.guide.mode==='local'?'Perguntas para orientar sua leitura':'Leve estas ideias com você'}</h3><ul class="key-points">${s.keyPoints.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${s.quote?`<details class="source"><summary>${icon('file')}Conferir trecho do artigo · ${esc(s.sourceLabel)}</summary><blockquote>${esc(s.quote)}</blockquote><button class="text-button" data-action="original">Ler o texto completo ${icon('arrow')}</button></details>`:''}<label class="understood"><input type="checkbox" id="understood" ${a.completed.includes(s.id)?'checked':''}>Estudei esta etapa e consigo explicar a ideia principal</label></article><div class="lesson-controls"><button class="button" data-action="previous" ${step===0?'disabled':''}>${icon('left')}Etapa anterior</button><button class="button primary" data-action="next">${step===a.guide.sections.length-1?'Revisar o que aprendi':'Próxima etapa'}${icon('arrow')}</button></div></div></div>`;}
function glossaryHtml(a){return `<div class="section-heading" style="margin-top:25px"><div><h2>Um nome difícil. Uma ideia possível.</h2><p class="muted" style="font-size:12px;margin-top:9px">Definições gerais para apoiar sua leitura. Confira como o artigo usa cada termo.</p></div></div><div class="glossary-grid">${a.guide.glossary.map(g=>`<article class="term-card"><span class="pill">CONCEITO</span><h3 style="margin-top:13px">${esc(g.term)}</h3><p>${esc(g.definition)}</p><div class="example"><strong>Na prática:</strong> ${esc(g.example)}</div></article>`).join('')||'<div class="empty-state">Nenhum termo identificado. Use a IA para criar um glossário deste artigo.</div>'}</div>`;}
function cardsHtml(a){const cards=a.guide.flashcards;cardIndex=Math.min(cardIndex,cards.length-1);if(!cards.length)return '<div class="empty-state">Use a IA para criar cartões deste artigo.</div>';const c=cards[cardIndex];return `<div style="margin:25px 0 18px"><div class="section-heading"><h2>O que ficou com você?</h2><span class="tiny">Cartão ${cardIndex+1} de ${cards.length}</span></div><p class="muted" style="font-size:12px">Tente lembrar antes de revelar. Consultar o texto também faz parte.</p></div><div class="flashcard"><span class="eyebrow" style="margin-bottom:24px">${flipped?'RESPOSTA PARA CONFERIR':'TENTE RESPONDER COM SUAS PALAVRAS'}</span>${flipped?`<p>${esc(c.answer)}</p>`:`<h2>${esc(c.question)}</h2>`}<button class="button soft" data-action="flip">${icon(flipped?'reset':'spark')}${flipped?'Ver pergunta':'Revelar resposta'}</button></div><div class="lesson-controls" style="max-width:800px">${flipped?`<button class="button" data-action="card-again">${icon('review')}Quero rever</button><button class="button primary" data-action="card-known">${icon('check')}Consegui lembrar</button>`:`<button class="button" data-action="card-prev" ${cardIndex===0?'disabled':''}>${icon('left')}Anterior</button><button class="button" data-action="card-next">Próximo ${icon('arrow')}</button>`}</div><p class="privacy-note">${Object.values(a.review.cards||{}).filter(v=>v==='known').length} de ${cards.length} cartões marcados como lembrados · Autoavaliação, sem pressão.</p>`;}
function quizHtml(a){const qs=a.guide.quiz;if(!qs.length)return '<div class="empty-state">Use a IA para criar perguntas específicas deste artigo.</div>';quizIndex=Math.min(quizIndex,qs.length-1);const q=qs[quizIndex];return `<div style="margin-top:27px;max-width:800px"><div class="section-heading"><h2>Uma pausa para lembrar.</h2><span class="tiny">Pergunta ${quizIndex+1} de ${qs.length}</span></div><article class="lesson"><span class="eyebrow">${a.guide.mode==='local'?'LEITURA CIENTÍFICA · CONCEITOS GERAIS':'TESTE RÁPIDO · SEM NOTA'}</span><h2 style="font-size:25px">${esc(q.question)}</h2>${q.options.map((o,i)=>`<button class="quiz-option ${quizAnswer!==null?(i===q.correct?'correct':i===quizAnswer?'wrong':''):''}" data-quiz-answer="${i}" ${quizAnswer!==null?'disabled':''}>${String.fromCharCode(65+i)}. ${esc(o)} ${quizAnswer!==null&&i===q.correct?'✓':''}</button>`).join('')}${quizAnswer!==null?`<div class="quiz-feedback ${quizAnswer===q.correct?'':'wrong'}"><strong>${quizAnswer===q.correct?'Isso mesmo.':'Vamos olhar de novo.'}</strong><br>${esc(q.explanation)}</div>`:''}</article><div class="lesson-controls"><button class="button" data-action="quiz-restart">${icon('reset')}Recomeçar</button>${quizAnswer!==null?`<button class="button primary" data-action="quiz-next">${quizIndex===qs.length-1?'Finalizar revisão':'Próxima pergunta'}${icon('arrow')}</button>`:''}</div></div>`;}
function notesHtml(a){return `<h2 class="notes-title">Seu entendimento, com suas palavras.</h2><p class="muted" style="font-size:12px;margin-bottom:20px">O que o estudo investigou? O que encontrou? Qual é a principal ressalva?</p><label for="note-editor" class="tiny">Minhas anotações</label><textarea id="note-editor" class="note-editor" maxlength="50000" placeholder="Comece por uma ideia. Conecte com algo que você já aprendeu…">${esc(a.notes)}</textarea><div class="stat-row"><span id="note-status" class="tiny">Salvo neste navegador</span><button class="text-button" data-action="export-markdown">${icon('download')}Baixar minhas anotações</button></div>`;}
function originalHtml(a){return `<div style="margin-top:25px"><div class="section-heading"><h2>Volte à fonte sempre que precisar.</h2><button class="text-button" data-action="download-original">${icon('download')}Baixar texto</button></div><div class="notice">${a.synthetic?'Este texto é um exemplo didático fictício.':'Este é o texto importado. A extração de PDF pode alterar a ordem de colunas, tabelas e fórmulas; confira o PDF para detalhes.'}</div><details class="original" open><summary>Texto completo · ${a.text.split(/\s+/).length.toLocaleString('pt-BR')} palavras</summary><div class="original-text">${esc(a.text)}</div></details></div>`;}
function setStep(n){stopSpeech();step=n;study();document.querySelector('.lesson h2')?.scrollIntoView({block:'center',behavior:'smooth'})}
function reviewPage(){shell(`<div class="greeting">${icon('review')}RELEMBRAR TAMBÉM É APRENDER</div><div class="page-intro"><div><h1>Dê espaço para<br><em>o conhecimento ficar.</em></h1><p>Uma pergunta por vez. Escolha um artigo para rever sem pressão.</p></div></div><div class="review-list">${data.articles.map(a=>`<article class="review-item"><div class="icon-tile">${icon('review')}</div><div><h3>${esc(a.title)}</h3><p>${a.guide.flashcards.length} cartões · ${a.guide.quiz.length} perguntas ${a.synthetic?'· exemplo fictício':''}</p><span class="pill">${Object.values(a.review.cards||{}).filter(v=>v==='known').length} CARTÕES LEMBRADOS</span></div><button class="button primary" data-review="${esc(a.id)}">Revisar ${icon('arrow')}</button></article>`).join('')||'<div class="empty-state">Importe seu primeiro artigo para começar a revisar.</div>'}</div><div class="notice green">A marcação dos cartões é sua autoavaliação. Você pode rever quantas vezes quiser; seu ritmo não é uma competição.</div>`);app.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{studyTab='cards';cardIndex=0;flipped=false;navigate('study/'+encodeURIComponent(b.dataset.review))})}
function notesPage(){shell(`<div class="greeting">${icon('note')}ESCREVER PARA CONECTAR</div><div class="page-intro"><div><h1>Suas ideias,<br><em>em um só lugar.</em></h1><p>Anotações de cada artigo. Escreva como se estivesse explicando a um colega.</p></div></div>${data.articles.map(a=>`<article class="help-card" style="margin:15px 0"><span class="pill">${a.synthetic?'EXEMPLO FICTÍCIO':'MEU ARTIGO'}</span><h2>${esc(a.title)}</h2><p style="white-space:pre-wrap;max-height:150px;overflow:hidden">${esc(a.notes||'Sua página ainda está em branco. Um bom começo: “A pergunta deste estudo é…”')}</p><button class="text-button" style="margin-top:15px" data-note="${esc(a.id)}">Abrir anotações ${icon('arrow')}</button></article>`).join('')||'<div class="empty-state">Adicione um artigo para abrir seu caderno.</div>'}`);app.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>{studyTab='notes';navigate('study/'+encodeURIComponent(b.dataset.note))})}
function helpPage(){shell(`<div class="greeting">${icon('leaf')}APRENDER PODE SER MAIS LEVE</div><div class="page-intro"><div><h1>O artigo é complexo.<br><em>O caminho pode ser simples.</em></h1><p>Um espaço de estudo pensado para reduzir a sobrecarga, com etapas curtas e escolhas claras.</p></div></div><div class="help-grid">${[['01','Comece pelo seu artigo','Importe um PDF com texto selecionável, TXT ou Markdown. Se tiver um PDF escaneado, use OCR em outro aplicativo e cole o texto aqui.'],['02','Entenda antes de decorar','O modo local organiza trechos e perguntas de leitura. A IA pode criar uma explicação didática, exemplos, conceitos e revisão a partir do seu artigo.'],['03','Escolha uma etapa por vez','Use o modo foco, aumente o texto ou ouça a explicação. O temporizador é opcional: uma pausa não apaga seu progresso.'],['04','Teste o que ficou','Explique com suas palavras, revele os flashcards e faça o teste rápido. Volte ao trecho original para conferir números e conclusões.']].map(([n,t,p])=>`<article class="help-card"><span class="pill">${n}</span><h2>${t}</h2><p>${p}</p></article>`).join('')}</div><article class="help-card"><h2>Essencial agora. Detalhes depois.</h2><p>Priorize a pergunta do estudo, quem participou, o que foi feito, o resultado e os limites da conclusão. Técnicas estatísticas e debates específicos podem entrar em uma segunda passagem, conforme a disciplina e a orientação do professor. Nenhuma parte é descartável para sempre.</p></article><div class="notice">O Lume é uma ferramenta de estudo, sem garantia de benefício clínico para TDAH. Explicações de IA podem conter erros. Um artigo isolado não estabelece consenso científico nem orienta uma decisão clínica por si só.</div><div class="help-grid"><article class="help-card"><h2>Seu espaço é seu.</h2><p>Artigos, anotações e progresso ficam no armazenamento deste navegador. Não há sincronização automática. Exporte uma cópia antes de limpar os dados ou trocar de dispositivo. Ao usar IA, você escolhe enviar o texto ao serviço utilizado.</p><button class="text-button" data-action="backup" style="margin-top:13px">${icon('download')}Exportar biblioteca</button></article><article class="help-card"><h2>Leve o Lume com você.</h2><p>O código inclui um servidor local e integração opcional com a API da OpenAI. Também é possível usar sua conversa no ChatGPT para criar um guia e importá-lo aqui.</p><button class="text-button" data-action="settings" style="margin-top:13px">${icon('settings')}Preferências e cópias</button></article></div>`)}
function modal(title,body,actions=''){stopSpeech();dc.innerHTML=`<div class="dialog-header"><h2>${title}</h2><button id="close-dialog" aria-label="Fechar">${icon('close')}</button></div>${body}${actions?`<div class="dialog-actions">${actions}</div>`:''}`;dc.querySelector('#close-dialog').onclick=()=>dialog.close();dc.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b));if(!dialog.open)dialog.showModal();}
function pickFile(){document.querySelector('#article-file').click()}
function pasteModal(){modal('Uma leitura começa aqui.',`<p class="dialog-description">Cole o artigo completo ou um trecho. O guia só pode trabalhar com o texto que você fornecer.</p><form id="paste-form"><label class="form-field">Título do artigo<input id="article-title" required maxlength="500" placeholder="Como se chama esta leitura?"></label><label class="form-field">Texto do artigo<textarea id="article-text" required minlength="100" maxlength="150000" placeholder="Cole o resumo, o artigo completo ou uma seção…"></textarea></label><p class="tiny">De 100 a 150.000 caracteres. O modo local organiza o texto sem enviá-lo a um serviço externo.</p><div class="dialog-actions"><button class="button primary" type="submit">Criar meu percurso ${icon('arrow')}</button></div></form>`);dc.querySelector('#paste-form').onsubmit=e=>{e.preventDefault();addArticle(dc.querySelector('#article-text').value,dc.querySelector('#article-title').value)}}
function addArticle(text,title){if(text.trim().length<100){toast('Precisamos de pelo menos 100 caracteres para organizar a leitura.');return}if(text.length>150000){toast('Este texto é grande. Importe uma seção de até 150.000 caracteres.');return}if(data.articles.length>=20){toast('Sua biblioteca tem 20 artigos. Exporte e remova um para adicionar outro.');return}const a={id:crypto.randomUUID(),title:title.trim().slice(0,500)||'Meu artigo',text,guide:analyzeArticle(text,title),completed:[],notes:'',review:{},created:Date.now()};data.articles.unshift(a);persist();dialog.close();openStudy(a.id);toast('Artigo importado. Vamos começar pela primeira ideia.')}
async function readFile(file){if(!file)return;if(file.size>20*1024*1024){toast('Escolha um arquivo de até 20 MB.');return}const name=file.name.toLowerCase();try{if(name.endsWith('.json')){importBackup(JSON.parse(await file.text()));return}if(name.endsWith('.pdf')){modal('Preparando sua leitura…','<div class="loading-message"><span class="spinner"></span><span id="pdf-progress">Lendo o PDF no seu navegador…</span></div><p class="tiny">O arquivo não está sendo enviado. PDFs escaneados precisam de OCR.</p>');let pdfjs,pdfWorker;try{pdfjs=await import('./vendor/pdf.mjs');pdfWorker=new URL('./vendor/pdf.worker.mjs',import.meta.url).href}catch{pdfjs=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.mjs');pdfWorker='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.mjs'}pdfjs.GlobalWorkerOptions.workerSrc=pdfWorker;const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,useSystemFonts:true}).promise;try{if(pdf.numPages>100)throw Error('Este PDF tem mais de 100 páginas. Separe o artigo ou importe uma seção.');let text='';for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i),c=await p.getTextContent();text+=`\n\n[ Página ${i} ]\n`+c.items.map(it=>it.str+(it.hasEOL?'\n':' ')).join('');if(text.length>150000)throw Error('O texto ultrapassou 150.000 caracteres. Divida o PDF em seções.');const label=dc.querySelector('#pdf-progress');if(label)label.textContent=`Organizando a página ${i} de ${pdf.numPages}…`;p.cleanup()}if(text.replace(/\[ Página \d+ \]/g,'').trim().length<100)throw Error('Não encontramos texto suficiente. Este PDF pode ser escaneado; use OCR e cole o texto.');addArticle(text,file.name.replace(/\.pdf$/i,''))}finally{pdf.destroy()}return}if(!/\.(txt|md)$/i.test(file.name))throw Error('Escolha um arquivo PDF, TXT, Markdown ou uma cópia JSON do Lume.');addArticle(await file.text(),file.name.replace(/\.(txt|md)$/i,''))}catch(e){modal('Vamos tentar de outro jeito.',`<p class="dialog-description">${esc(e.message.includes('Failed to fetch dynamically')?'O leitor de PDF não carregou. Use a versão local completa ou cole o texto do artigo.':e.message)}</p><button class="button primary" data-action="paste">${icon('note')}Colar o texto</button>`)}}
function normalizeArticle(raw){if(!raw||typeof raw.title!=='string'||typeof raw.text!=='string'||raw.text.length>150000||typeof raw.notes!=='string'||raw.notes.length>50000)throw Error('Esta cópia de artigo não é válida.');const guide=validateGuide(raw.guide,raw.text);return {...raw,id:crypto.randomUUID(),guide,completed:Array.isArray(raw.completed)?raw.completed.filter(x=>typeof x==='string'&&guide.sections.some(s=>s.id===x)):[],review:raw.review&&typeof raw.review==='object'?raw.review:{},synthetic:guide.mode==='demo',created:Date.now()}}
function importBackup(value){if(value?.version!==1)throw Error('Versão da cópia não reconhecida.');let items;if(value.format==='lume-library'&&Array.isArray(value.articles))items=value.articles;else if(value.format==='lume-article')items=[value.article];else throw Error('Use uma cópia exportada pelo Lume. Para importar um guia de IA, abra o artigo e escolha “Explicar com IA”.');if(items.length+data.articles.length>20)throw Error('A biblioteca comporta 20 artigos. Exporte e remova alguns antes de restaurar.');const validated=items.map(normalizeArticle);modal('Restaurar sua cópia?',`<p class="dialog-description">${validated.length} artigo(s) serão adicionados à biblioteca, com suas anotações e progresso. Seus estudos atuais serão preservados.</p>`,`<button id="confirm-restore" class="button primary">Adicionar à biblioteca</button>`);dc.querySelector('#confirm-restore').onclick=()=>{data.articles.unshift(...validated);persist();dialog.close();navigate('library');toast('Cópia restaurada. Seus estudos estão aqui.')}}
function settingsModal(){modal('Do seu jeito.',`<p class="dialog-description">Escolha o que deixa seu momento de estudo mais confortável.</p><label class="check-row"><input id="large-text" type="checkbox" ${data.settings.large?'checked':''}>Texto maior durante o estudo</label><label class="form-field">Duração da sessão de foco<select id="session-minutes">${[5,10,15,25].map(n=>`<option value="${n}" ${data.settings.minutes===n?'selected':''}>${n} minutos</option>`).join('')}</select></label><p class="tiny">Você pode pausar ou reiniciar. Nenhuma meta obrigatória.</p><div class="divider"></div><div class="stat-row"><strong>Explicação automática com IA</strong><span class="status-tag">${aiAvailable?'Disponível':'Não configurada'}</span></div><p class="dialog-description">${aiAvailable?'A API está configurada no servidor. O texto só é enviado ao escolher gerar uma explicação.':'A leitura local já funciona. Você também pode copiar um pedido para o ChatGPT e importar a resposta. O código inclui integração opcional com a API da OpenAI.'}</p><div class="divider"></div><div class="stat-row"><strong>Sua biblioteca</strong><span class="tiny">${data.articles.length} artigo(s)</span></div><button class="button small" data-action="backup">${icon('download')}Exportar cópia</button> <button class="button small" data-action="restore">${icon('upload')}Restaurar cópia</button><p class="privacy-note">Os dados ficam neste navegador e podem ser apagados ao limpar os dados do site. Guarde uma cópia regularmente.</p><div class="dialog-actions"><button id="save-settings" class="button primary">Salvar preferências ${icon('check')}</button></div>`);dc.querySelector('#save-settings').onclick=()=>{data.settings.large=dc.querySelector('#large-text').checked;const n=Number(dc.querySelector('#session-minutes').value);if(n!==data.settings.minutes){data.settings.minutes=n;resetTimer()}persist();dialog.close();render();toast('Seu espaço, do seu jeito.')}}
function articleMenu(id){const a=data.articles.find(x=>x.id===id);modal('Seu artigo.',`<p class="dialog-description">${esc(a.title)}</p><div style="display:grid;gap:10px"><button class="button" id="menu-export">${icon('download')}Exportar artigo, guia e anotações</button><button class="button danger" id="menu-delete">${icon('trash')}Remover da biblioteca</button></div>`);dc.querySelector('#menu-export').onclick=()=>exportArticle(a);dc.querySelector('#menu-delete').onclick=()=>{modal('Remover este artigo?',`<p class="dialog-description">O artigo e suas anotações serão removidos deste navegador. Exporte uma cópia se quiser guardar seu estudo.</p>`,`<button class="button" id="cancel-delete">Cancelar</button><button class="button danger" id="confirm-delete">Remover artigo</button>`);dc.querySelector('#cancel-delete').onclick=()=>dialog.close();dc.querySelector('#confirm-delete').onclick=()=>{data.articles=data.articles.filter(x=>x.id!==id);persist();dialog.close();render();toast('Artigo removido.')}}}
function aiModal(){const a=article();modal('Vamos dar clareza ao artigo.',`<p class="dialog-description">Crie uma explicação em português, pensada para quem está começando a estudar Psicologia. As conclusões devem permanecer ligadas ao texto original.</p>${aiAvailable?`<div class="ai-box"><h3>Gerar dentro do Lume</h3><p>O texto deste artigo será enviado à API da OpenAI configurada no servidor. A API pode gerar custos na conta responsável.</p><button class="button primary" id="generate-ai">${icon('spark')}Gerar explicação didática</button></div>`:`<div class="notice">A explicação automática por API ainda não está configurada. Você pode usar sua conversa no ChatGPT pelo caminho abaixo.</div>`}<div class="ai-box"><h3>Usar com o ChatGPT</h3><p>1. Copie o pedido preparado com o seu artigo.<br>2. Cole no ChatGPT e peça a resposta em JSON.<br>3. Volte aqui e importe o JSON para montar seu percurso.</p><button class="button soft" id="copy-prompt">${icon('copy')}Copiar pedido + artigo</button><a class="button" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">Abrir ChatGPT ${icon('external')}</a><label class="form-field">Cole a resposta JSON do ChatGPT<textarea id="ai-json" placeholder='{"title": "…", "overview": "…", ...}' maxlength="200000" style="min-height:110px"></textarea></label><button class="button primary" id="import-ai">${icon('upload')}Aplicar guia ao artigo</button><p id="ai-error" class="error-message" role="alert"></p></div><p class="privacy-note">O guia substituirá o percurso atual e reiniciará suas marcações de estudo e revisão. Suas anotações e o original serão preservados.</p>`);
dc.querySelector('#copy-prompt').onclick=()=>copyText(buildChatGPTPrompt(a.text,a.title));dc.querySelector('#import-ai').onclick=()=>{try{let raw=dc.querySelector('#ai-json').value.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');applyGuide(a,validateGuide({...JSON.parse(raw),mode:'ai'},a.text))}catch(e){dc.querySelector('#ai-error').textContent='Não conseguimos aplicar o guia: '+e.message}};const gen=dc.querySelector('#generate-ai');if(gen)gen.onclick=async()=>{gen.disabled=true;gen.textContent='Preparando sua explicação…';try{const r=await fetch('/api/study',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:a.text,title:a.title})});const result=await r.json();if(!r.ok)throw Error(result.error||'Não foi possível gerar o guia agora.');applyGuide(a,validateGuide(result.guide,a.text))}catch(e){gen.disabled=false;gen.textContent='Tentar novamente';dc.querySelector('#ai-error').textContent=e.message}};}
function applyGuide(a,guide){a.guide=guide;a.completed=[];a.review={};step=0;cardIndex=0;quizIndex=0;quizAnswer=null;studyTab='guide';persist();dialog.close();study();toast('Seu guia está pronto. Vamos por partes.')}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Pedido copiado. Cole na sua conversa no ChatGPT.')}catch{modal('Seu pedido para o ChatGPT.',`<p class="dialog-description">Selecione e copie o texto abaixo. Ele já inclui seu artigo e as instruções do guia.</p><textarea id="copy-fallback" class="note-editor" readonly>${esc(text)}</textarea>`);dc.querySelector('#copy-fallback').select()}}
function saveFile(name,content,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const slug=t=>t.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'-').slice(0,70).toLowerCase();
function exportArticle(a){saveFile('lume-'+slug(a.title)+'.json',JSON.stringify({format:'lume-article',version:1,article:a},null,2));toast('Cópia do estudo preparada para download.')}
function markdown(a){return `# ${a.title}\n\n${a.synthetic?'Exemplo fictício para estudo.\n\n':''}${a.guide.overview}\n\n${a.guide.sections.map(s=>`## ${s.title}\n\n${s.summary}\n\n${s.keyPoints.map(p=>'- '+p).join('\n')}\n\n${s.quote?'> '+s.quote.replace(/\n/g,'\n> '):''}`).join('\n\n')}\n\n## Conceitos\n\n${a.guide.glossary.map(g=>`- **${g.term}:** ${g.definition} Exemplo: ${g.example}`).join('\n')}\n\n## Minhas anotações\n\n${a.notes||'(Ainda sem anotações.)'}\n\n## Limitações e cuidados\n\n${a.guide.limitations.map(p=>'- '+p).join('\n')}\n\nExportado do Lume. Modo: ${a.guide.mode}. Confira as explicações com o artigo original.\n`;}
function formatTime(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function updateTimer(){if(timerRunning){timerLeft=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));if(timerLeft===0){timerRunning=false;clearInterval(timerInterval);toast('Sua sessão terminou. Faça uma pausa e volte quando quiser.')}}document.querySelectorAll('[data-timer]').forEach(x=>x.textContent=formatTime(timerLeft));document.querySelectorAll('[data-timer-label]').forEach(x=>x.textContent=timerRunning?'Pausar':'Começar')}
function toggleTimer(){if(timerRunning){timerLeft=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));timerRunning=false;clearInterval(timerInterval)}else{if(timerLeft<=0)timerLeft=data.settings.minutes*60;timerRunning=true;timerDeadline=Date.now()+timerLeft*1000;timerInterval=setInterval(updateTimer,500)}updateTimer()}
function resetTimer(){timerRunning=false;clearInterval(timerInterval);timerLeft=data.settings.minutes*60;updateTimer()}
function stopSpeech(){if('speechSynthesis'in window)window.speechSynthesis.cancel()}
function speak(){if(!('speechSynthesis'in window)){toast('Este navegador não oferece leitura em voz alta.');return}if(window.speechSynthesis.speaking){stopSpeech();toast('Leitura pausada.');return}const a=article();let text=studyTab==='guide'?[a.guide.sections[step].question,a.guide.sections[step].summary,...a.guide.sections[step].keyPoints].join('. '):studyTab==='glossary'?a.guide.glossary.map(g=>g.term+'. '+g.definition+'. '+g.example).join('. '):studyTab==='cards'?(flipped?a.guide.flashcards[cardIndex]?.answer:a.guide.flashcards[cardIndex]?.question):studyTab==='notes'?a.notes:studyTab==='quiz'?a.guide.quiz[quizIndex]?.question:a.text;if(!text){toast('Ainda não há texto para ouvir.');return}const utter=new SpeechSynthesisUtterance(text);utter.lang='pt-BR';utter.rate=.93;const voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase()==='pt-br');if(voice)utter.voice=voice;speechSynthesis.speak(utter);toast('Lendo em voz alta. Clique em ouvir novamente para parar.')}
function action(act,b){const a=article();switch(act){case'upload':pickFile();break;case'paste':pasteModal();break;case'demo':if(!data.articles.some(a=>a.id==='demo')){data.articles.push(demo());persist()}dialog.close();openStudy('demo');break;case'settings':settingsModal();break;case'library':navigate('library');break;case'backup':saveFile('lume-biblioteca.json',JSON.stringify({format:'lume-library',version:1,articles:data.articles,settings:data.settings},null,2));toast('Cópia da biblioteca preparada para download.');break;case'restore':document.querySelector('#backup-file').click();break;case'about':dialog.close();navigate('help');break;case'timer':toggleTimer();break;case'timer-reset':resetTimer();break;case'next':if(step<a.guide.sections.length-1)setStep(step+1);else{studyTab='cards';flipped=false;cardIndex=0;study()}break;case'previous':if(step>0)setStep(step-1);break;case'focus':focus=!focus;if(focus){studyTab='guide';study();toast('Só você e uma ideia. Use o botão no topo para sair.')}else study();break;case'speak':speak();break;case'original':studyTab='original';study();break;case'export-article':modal('Leve seu estudo com você.',`<p class="dialog-description">A cópia JSON permite restaurar tudo no Lume. O Markdown é um documento de texto para ler e compartilhar.</p><button class="button primary" id="export-json">${icon('download')}Cópia completa · JSON</button> <button class="button" data-action="export-markdown">${icon('note')}Guia e notas · Markdown</button>`);dc.querySelector('#export-json').onclick=()=>exportArticle(a);break;case'export-markdown':saveFile('lume-'+slug(a.title)+'.md',markdown(a),'text/markdown;charset=utf-8');toast('Guia e anotações preparados para download.');break;case'download-original':saveFile(slug(a.title)+'.txt',a.text,'text/plain;charset=utf-8');break;case'ai':aiModal();break;case'flip':flipped=!flipped;study();break;case'card-prev':cardIndex=Math.max(0,cardIndex-1);flipped=false;study();break;case'card-next':cardIndex=(cardIndex+1)%a.guide.flashcards.length;flipped=false;study();break;case'card-again':case'card-known':a.review.cards={...(a.review.cards||{}),[cardIndex]:act==='card-known'?'known':'again'};persist();if(cardIndex===a.guide.flashcards.length-1){toast('Uma rodada feita. Volte aos cartões que quiser rever.');cardIndex=0}else cardIndex++;flipped=false;study();break;case'quiz-next':if(quizIndex===a.guide.quiz.length-1){modal('Mais uma conexão feita.',`<p class="dialog-description">Você respondeu às ${a.guide.quiz.length} perguntas desta rodada. Revise o feedback e anote o que ainda quer entender.</p><button class="button primary" id="review-notes">${icon('note')}Anotar o que aprendi</button>`);dc.querySelector('#review-notes').onclick=()=>{dialog.close();studyTab='notes';study()}}else{quizIndex++;quizAnswer=null;study()}break;case'quiz-restart':quizIndex=0;quizAnswer=null;study();break;}}
window.addEventListener('hashchange',()=>{stopSpeech();render();window.scrollTo(0,0)});dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close()}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&focus){focus=false;study()}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateTimer()});window.addEventListener('pagehide',stopSpeech);
render();if(location.protocol!=='file:')fetch('/api/status',{signal:AbortSignal.timeout(3000)}).then(r=>r.ok?r.json():null).then(s=>{aiAvailable=Boolean(s?.aiAvailable);if(aiAvailable)render()}).catch(()=>{});
